function doPost(e) {
  var ss = SpreadsheetApp.openById("1ddb25TMCxdqOPE-545lYuIGsv95qxfGyloFjUgzRZvk");
  var sh = ss.getSheets()[0];
  var d = JSON.parse(e.postData.contents);
  if (sh.getLastRow() === 0) sh.appendRow(["Date","Type","Service","Nom","Téléphone","Localisation","Bien/projet","Budget","Profil","Besoin","Délai","Consentement","Statut","Partenaire","Commission"]);
  sh.appendRow([d.date,d.type,d.service,d.nom,d.tel,d.lieu,d.bien,d.budget,d.profil,d.besoin,d.delai,d.consentement,"Nouveau","",""]);
  return ContentService.createTextOutput("ok");
}

function testEcriture() {
  var ss = SpreadsheetApp.openById("1ddb25TMCxdqOPE-545lYuIGsv95qxfGyloFjUgzRZvk");
  var sh = ss.getSheets()[0];
  sh.appendRow(["TEST", new Date(), "Test de connexion", "Ligne à supprimer"]);
}

function oueEstLaFeuille() {
  var ss = SpreadsheetApp.openById("1ddb25TMCxdqOPE-545lYuIGsv95qxfGyloFjUgzRZvk");
  Logger.log("Nom : " + ss.getName());
  Logger.log("Onglet : " + ss.getSheets()[0].getName());
  Logger.log("Lignes remplies : " + ss.getSheets()[0].getLastRow());
  Logger.log("Adresse : " + ss.getUrl());
}
